const css = `
.hj-root {
  --hj-maroon: #6B2D35;
  --hj-rose: #8C6068;
  --hj-cream: #F5EEE6;
  background: var(--hj-cream);
  color: var(--hj-maroon);
  font-family: 'Cormorant Garamond', Georgia, serif;
  text-align: center;
  max-width: 420px;
  margin: 0 auto;
  padding: 16px 20px 40px;
  box-sizing: border-box;
}

.hj-svg {
  width: 100%;
  max-width: 400px;
  height: auto;
  display: block;
  margin: 0 auto;
  overflow: visible;
}

.hj-p {
  fill: var(--hj-maroon);
  fill-rule: evenodd;
}

.hj-title {
  font-family: 'Great Vibes', 'Brush Script MT', cursive;
  font-weight: 400;
  font-size: 3.1rem;
  margin: 4px 0 0;
  filter: drop-shadow(0 1px 1px rgba(255, 255, 255, 0.7));
}

.hj-sub {
  font-size: 1.25rem;
  margin: 0 0 18px;
  color: #7A3340;
}

.hj-ticket {
  background: linear-gradient(135deg, #9a6c74, #7a525a);
  color: #FFF8EC;
  border-radius: 16px;
  padding: 16px 14px 14px;
  box-shadow: 0 10px 24px rgba(107, 45, 53, 0.25);
  margin: 0 auto;
  max-width: 380px;
}

.hj-timer-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-bottom: 8px;
}

.hj-time-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 46px;
}

.hj-time-val {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 1.75rem;
  font-weight: 600;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
}

.hj-time-lbl {
  font-size: 0.65rem;
  letter-spacing: 0.16em;
  opacity: 0.85;
  margin-top: 4px;
  font-weight: 500;
}

.hj-time-sep {
  font-size: 1.3rem;
  font-weight: 300;
  opacity: 0.6;
  margin-bottom: 12px;
}

.hj-ticket-sub {
  display: block;
  letter-spacing: .25em;
  font-size: .78rem;
  opacity: 0.95;
  border-top: 1px solid rgba(255, 248, 236, 0.2);
  padding-top: 8px;
  margin-top: 4px;
}

.hj-bless {
  font-style: italic;
  font-size: 1.15rem;
  margin: 22px 8px 0;
  color: #5A252C;
}

.hj-fade {
  opacity: 0;
  animation: hj-up .7s ease forwards;
}

.hj-f1 { animation-delay: .3s; }
.hj-f2 { animation-delay: .5s; }
.hj-f3 { animation-delay: .7s; }
.hj-f4 { animation-delay: .9s; }

@keyframes hj-up {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: none; }
}

.hj-band {
  animation: hj-sway 5s ease-in-out infinite;
}

@keyframes hj-sway {
  0%, 100% { transform: translateX(0); }
  20% { transform: translateX(calc(var(--a) * 2.8px)); }
  40% { transform: translateX(calc(var(--a) * .6px)); }
  60% { transform: translateX(calc(var(--a) * 2.4px)); }
  80% { transform: translateX(0); }
}

/* Frequent, radiant ring sparkle animation (~1.6s rapid cycle) */
.hj-sp {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: hj-spark 1.6s ease-out infinite;
}

.hj-mehendi {
  opacity: 0.92;
  filter: drop-shadow(0 0.5px 1px rgba(107, 45, 53, 0.15));
}

@keyframes hj-spark {
  0% { opacity: 0; transform: scale(.1) rotate(0deg); }
  22% { opacity: 1; transform: scale(1.35) rotate(45deg); }
  50% { opacity: 0; transform: scale(.25) rotate(90deg); }
  100% { opacity: 0; transform: scale(.25) rotate(90deg); }
}

@media (prefers-reduced-motion: reduce) {
  .hj-band, .hj-sp { animation: none !important; }
  .hj-fade { opacity: 1 !important; animation: none !important; }
}
`;

function Sparkle({
  x,
  y,
  delay,
  scale = 1,
}: {
  x: number;
  y: number;
  delay: number;
  scale?: number;
}) {
  return (
    <g transform={`translate(${x} ${y}) scale(${scale})`}>
      <g className="hj-sp" style={{ animationDelay: `${delay}s` }}>
        <path d={STAR} fill="#D9A23A" />
        <path d={STAR} transform="scale(.55)" fill="#fff" />
        <circle r="3" fill="#fff" />
      </g>
    </g>
  );
}

function BoyMehendi() {
  return (
    <g
      className="hj-mehendi hj-mehendi-boy"
      transform="translate(236 246) rotate(47)"
      stroke="#6B2D35"
      fill="none"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      {/* Central Groom Mandala */}
      <circle cx="0" cy="0" r="2.8" fill="#6B2D35" stroke="none" />
      <circle cx="0" cy="0" r="6.5" strokeWidth="1.2" />
      <circle cx="0" cy="0" r="10.5" strokeWidth="0.9" strokeDasharray="1.5 2" />

      {/* 8 Traditional Petals */}
      <path
        d="
          M0 -15 C-2.5 -11 -2.5 -9 0 -8 C2.5 -9 2.5 -11 0 -15 Z
          M10.6 -10.6 C7.5 -9 5.5 -7 7 -4.5 C9.5 -5.5 11.5 -7 10.6 -10.6 Z
          M15 0 C11 -2.5 9 -2.5 8 0 C9 2.5 11 2.5 15 0 Z
          M10.6 10.6 C11.5 7 9.5 5.5 7 4.5 C5.5 7 7.5 9 10.6 10.6 Z
          M0 15 C2.5 11 2.5 9 0 8 C-2.5 9 -2.5 11 0 15 Z
          M-10.6 10.6 C-7.5 9 -5.5 7 -7 4.5 C-9.5 5.5 -11.5 7 -10.6 10.6 Z
          M-15 0 C-11 2.5 -9 2.5 -8 0 C-9 -2.5 -11 -2.5 -15 0 Z
          M-10.6 -10.6 C-11.5 -7 -9.5 -5.5 -7 -4.5 C-5.5 -7 -7.5 -9 -10.6 -10.6 Z
        "
        fill="#6B2D35"
        fillOpacity="0.22"
        strokeWidth="1.1"
      />

      {/* Cardinal accent dots */}
      <circle cx="0" cy="-18" r="1.3" fill="#6B2D35" stroke="none" />
      <circle cx="18" cy="0" r="1.3" fill="#6B2D35" stroke="none" />
      <circle cx="0" cy="18" r="1.3" fill="#6B2D35" stroke="none" />
      <circle cx="-18" cy="0" r="1.3" fill="#6B2D35" stroke="none" />

      {/* Trailing leafy vine towards fingers (+X) */}
      <path d="M15 0 Q28 4 40 1" strokeWidth="1.2" />
      <path d="M22 2 Q25 7 29 4 Q26 1 22 2 Z" fill="#6B2D35" strokeWidth="0.7" />
      <path d="M31 3 Q34 -2 37 1 Q34 4 31 3 Z" fill="#6B2D35" strokeWidth="0.7" />
      <circle cx="40" cy="1" r="1.5" fill="#6B2D35" stroke="none" />

      {/* Vine towards wrist (-X) */}
      <path d="M-15 0 Q-26 -4 -36 -1" strokeWidth="1.2" />
      <path d="M-22 -2 Q-25 -7 -29 -4 Q-26 -1 -22 -2 Z" fill="#6B2D35" strokeWidth="0.7" />
      <circle cx="-36" cy="-1" r="1.5" fill="#6B2D35" stroke="none" />
    </g>
  );
}

/* ---------- Rajasthani mehendi helpers (girl's hand) ---------- */
const rad = (d: number) => (d * Math.PI) / 180;

function Dots({ n, r, s = 1.2, start = 0 }: { n: number; r: number; s?: number; start?: number }) {
  return (
    <>
      {Array.from({ length: n }, (_, i) => {
        const a = rad(start + (i * 360) / n);
        return <circle key={i} cx={r * Math.cos(a)} cy={r * Math.sin(a)} r={s} fill={M} stroke="none" />;
      })}
    </>
  );
}

function Petals({
  n, r0, r1, w, solid = true, sw = 1.3,
}: { n: number; r0: number; r1: number; w: number; solid?: boolean; sw?: number }) {
  const k = r1 - r0;
  const d = `M0 ${-r0} C${-w} ${-(r0 + k * 0.35)} ${-w} ${-(r1 - k * 0.2)} 0 ${-r1} C${w} ${-(r1 - k * 0.2)} ${w} ${-(r0 + k * 0.35)} 0 ${-r0}Z`;
  return (
    <>
      {Array.from({ length: n }, (_, i) => (
        <path
          key={i}
          d={d}
          transform={`rotate(${(i * 360) / n})`}
          fill={solid ? M : "none"}
          fillOpacity={solid ? 0.5 : 1}
          strokeWidth={sw}
        />
      ))}
    </>
  );
}

function Leaf({ x, y, rot, s = 1 }: { x: number; y: number; rot: number; s?: number }) {
  return (
    <path
      d="M0 0 Q3.4 -3.8 0 -8.5 Q-3.4 -3.8 0 0Z"
      transform={`translate(${x} ${y}) rotate(${rot}) scale(${s})`}
      fill={M}
      strokeWidth={0.8}
    />
  );
}

/* One finger: stem, alternating leaf pairs + chevrons, solid dipped fingertip */
function Finger({ x1, y1, x2, y2 }: { x1: number; y1: number; x2: number; y2: number }) {
  const dx = x2 - x1, dy = y2 - y1;
  const len = Math.hypot(dx, dy);
  const ang = (Math.atan2(dy, dx) * 180) / Math.PI;
  const ux = dx / len, uy = dy / len;
  const nx = -uy, ny = ux;
  const p = (t: number): [number, number] => [x1 + dx * t, y1 + dy * t];
  const [bx, by] = p(0.68), [cx, cy] = p(0.9);
  const steps = 5;
  return (
    <g>
      <path d={`M${x1} ${y1} L${bx} ${by}`} strokeWidth={1.8} />
      {Array.from({ length: steps }, (_, i) => {
        const [px, py] = p(((i + 0.5) / steps) * 0.66);
        return i % 2 === 0 ? (
          <g key={i}>
            <Leaf x={px} y={py} rot={ang + 90 - 58} s={1.25} />
            <Leaf x={px} y={py} rot={ang + 90 + 58} s={1.25} />
            <circle cx={px} cy={py} r="1.4" fill={M} stroke="none" />
          </g>
        ) : (
          <path
            key={i}
            d={`M${px + nx * 5} ${py + ny * 5} L${px + ux * 3.5} ${py + uy * 3.5} L${px - nx * 5} ${py - ny * 5}`}
            strokeWidth={1.5}
          />
        );
      })}
      <path d={`M${bx} ${by} L${cx} ${cy}`} strokeWidth={11} opacity={0.9} />
      <path d={`M${cx} ${cy} L${x2} ${y2}`} strokeWidth={5} opacity={0.9} />
      <circle cx={bx} cy={by} r="7.5" fill="none" strokeWidth={1.4} />
    </g>
  );
}

function GirlMehendi() {
  return (
    <g
      className="hj-mehendi hj-mehendi-girl"
      stroke={M}
      fill="none"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      {/* Curved maroon bangle */}
      <g transform="translate(515 188) rotate(41)">
        <path d="M-47 -9 Q0 2 47 -9 L47 12 Q0 23 -47 12 Z" fill={M} stroke="none" />
        <path d="M-43 -4 Q0 7 43 -4" stroke="#F5EEE6" strokeWidth={0.9} opacity={0.55} />
        <path
          d="M-42 5 Q0 16 42 5"
          stroke="#F5EEE6"
          strokeWidth={1.5}
          strokeDasharray="0.1 5"
          strokeLinecap="round"
          opacity={0.85}
        />
      </g>

      {/* Back of hand: bold sun mandala + leaf vine toward the bangle */}
      <g transform="translate(420 272) rotate(-40)">
        <g transform="scale(1.15)">
          <circle r="3.4" fill={M} stroke="none" />
          <circle r="6.5" strokeWidth={1.6} />
          <Petals n={8} r0={7.5} r1={17} w={5} />
          <Dots n={16} r={19.5} s={1.2} />
          <circle r="22.5" strokeWidth={1.5} />
          <Petals n={16} r0={23} r1={31} w={3} solid={false} sw={1.2} />
          <Dots n={16} r={34} s={1.1} start={11.25} />
          <circle r="37" strokeWidth={1.2} strokeDasharray="2 2.4" />
        </g>
        <path d="M48 0 L100 0" strokeWidth={1.8} />
        {[64, 78, 92].map((x) => (
          <g key={x}>
            <Leaf x={x} y={0} rot={48} s={1.3} />
            <Leaf x={x} y={0} rot={132} s={1.3} />
          </g>
        ))}
        <circle cx="100" cy="0" r="1.8" fill={M} stroke="none" />
      </g>

      {/* Fingers */}
      <Finger x1={350} y1={352} x2={324} y2={450} />
      <Finger x1={392} y1={385} x2={365} y2={450} />
    </g>
  );
}

export default function SurpriseHands({
  title = "Our Special Day!",
  subtitle = "Counting down to forever",
  date = "11th December, 2026",
  targetDate = "2026-12-11T10:00:00",
  eventName = "WEDDING CEREMONY",
  blessing = "With the heartfelt blessings of our families and the love of our dear ones, we begin a beautiful new chapter together.",
  className = "",
}: SurpriseHandsProps) {
  // Load Google Fonts once
  useEffect(() => {
    if (document.getElementById("hj-fonts")) return;
    const link = document.createElement("link");
    link.id = "hj-fonts";
    link.rel = "stylesheet";
    link.href = FONT_URL;
    document.head.appendChild(link);
  }, []);

  // Live countdown timer state
  const [timeLeft, setTimeLeft] = useState<{
    days: number;
    hours: number;
    minutes: number;
    seconds: number;
  }>({ days: 0, hours: 0, minutes: 0, seconds: 0 });

  useEffect(() => {
    const target = new Date(targetDate).getTime();

    const calculateTime = () => {
      const now = Date.now();
      const diff = Math.max(0, target - now);

      setTimeLeft({
        days: Math.floor(diff / (1000 * 60 * 60 * 24)),
        hours: Math.floor((diff / (1000 * 60 * 60)) % 24),
        minutes: Math.floor((diff / (1000 * 60)) % 60),
        seconds: Math.floor((diff / 1000) % 60),
      });
    };

    calculateTime();
    const intervalId = setInterval(calculateTime, 1000);
    return () => clearInterval(intervalId);
  }, [targetDate]);

  return (
    <section className={`hj-root ${className}`.trim()}>
      <style>{css}</style>

      <svg
        className="hj-svg"
        viewBox="0 0 580 490"
        role="img"
        aria-label="Two joined hands, each wearing a ring with frequent sparkles"
      >
        <defs>
          <g id="hj-girl">
            <path className="hj-p" d={GIRL_PATH} />
            <GirlMehendi />
          </g>
          <clipPath id="hj-top">
            <rect x="-50" y="-50" width="700" height={BAND_Y0 + 50.4} />
          </clipPath>
          {Array.from({ length: BANDS }, (_, i) => (
            <clipPath id={`hj-c${i}`} key={i}>
              <rect
                x="-50"
                y={BAND_Y0 + i * BAND_H}
                width="700"
                height={i < BANDS - 1 ? BAND_H + 0.7 : 300}
              />
            </clipPath>
          ))}
        </defs>

        {/* Boy's shirt cuff in maroon */}
        <path d={BOY_SHIRT_CUFF_PATH} fill="#6B2D35" />

        {/* Boy's hand (static) */}
        <path className="hj-p" d={BOY_PATH} />

        {/* Boy's Mehendi Design */}
        <BoyMehendi />

        {/* Girl's hand: static top + horizontal bands that sway progressively */}
        <g clipPath="url(#hj-top)">
          <use href="#hj-girl" />
        </g>
        {Array.from({ length: BANDS }, (_, i) => {
          const a = 5 * Math.pow((i + 1) / BANDS, 1.7);
          return (
            <g clipPath={`url(#hj-c${i})`} key={i}>
              <g className="hj-band" style={{ "--a": a.toFixed(2) } as React.CSSProperties}>
                <use href="#hj-girl" />
              </g>
            </g>
          );
        })}

        {/* Ring sparkles: staggered bursts on both rings */}
        <Sparkle x={275} y={317} delay={0.1} scale={1.1} />
        <Sparkle x={272} y={320} delay={0.9} scale={0.75} />
        <Sparkle x={370} y={338} delay={0.5} scale={1.2} />
        <Sparkle x={374} y={335} delay={1.3} scale={0.8} />
      </svg>

      <h1 className="hj-title hj-fade hj-f1">{title}</h1>
      <p className="hj-sub hj-fade hj-f2">{subtitle}</p>

      {/* Maroon Ticket with Live Countdown Timer */}
      <div className="hj-ticket hj-fade hj-f3">
        <div className="hj-timer-row">
          <div className="hj-time-unit">
            <span className="hj-time-val">{timeLeft.days}</span>
            <span className="hj-time-lbl">DAYS</span>
          </div>
          <span className="hj-time-sep">:</span>
          <div className="hj-time-unit">
            <span className="hj-time-val">{String(timeLeft.hours).padStart(2, "0")}</span>
            <span className="hj-time-lbl">HOURS</span>
          </div>
          <span className="hj-time-sep">:</span>
          <div className="hj-time-unit">
            <span className="hj-time-val">{String(timeLeft.minutes).padStart(2, "0")}</span>
            <span className="hj-time-lbl">MINS</span>
          </div>
          <span className="hj-time-sep">:</span>
          <div className="hj-time-unit">
            <span className="hj-time-val">{String(timeLeft.seconds).padStart(2, "0")}</span>
            <span className="hj-time-lbl">SECS</span>
          </div>
        </div>

        <span className="hj-ticket-sub">{eventName}</span>
      </div>

      <p className="hj-bless hj-fade hj-f4">{blessing}</p>
    </section>
  );
}